package apextest

import (
	"encoding/json"
	"path/filepath"
	"testing"
)

// Exact API53 constructor contracts in an explicit observed LA/en_US runAs context.
// The source is unchanged from the independently admitted contextual successor.
func TestRunTimeOverflowContracts(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeTimeOverflow53.cls"), "@IsTest private class GladeTimeOverflow53 {\n private static User actor(){\n  return new User(Alias='tm53',Email='time53@example.invalid',EmailEncodingKey='UTF-8',LastName='TimeContext',LanguageLocaleKey='en_US',LocaleSidKey='en_US',ProfileId=UserInfo.getProfileId(),TimeZoneSidKey='America/Los_Angeles',Username='time53.'+UserInfo.getOrganizationId()+'.'+String.valueOf(Datetime.now().getTime())+'@example.invalid');\n }\n private static void assertObserved(Object expected,Object actual,String label){\n  if(expected instanceof Map<String,Object>){\n   System.assert(actual instanceof Map<String,Object>,label+': map type');\n   Map<String,Object> want=(Map<String,Object>)expected;Map<String,Object> got=(Map<String,Object>)actual;\n   System.assertEquals(want.keySet(),got.keySet(),label+': exact fields');\n   for(String key:want.keySet())assertObserved(want.get(key),got.get(key),label+'.'+key);\n  }else if(expected instanceof List<Object>){\n   System.assert(actual instanceof List<Object>,label+': list type');\n   List<Object> want=(List<Object>)expected;List<Object> got=(List<Object>)actual;\n   System.assertEquals(want.size(),got.size(),label+': exact size');\n   for(Integer i=0;i<want.size();i++)assertObserved(want[i],got[i],label+'['+i+']');\n  }else{\n   System.assertEquals(expected,actual,label);\n   if(expected instanceof String)System.assert(((String)expected).equals((String)actual),label+': exact text');\n  }\n }\n private static void finish(String method,List<String> columns,List<Object> rows,Integer count){\n  System.assertEquals(count,rows.size(),method+': complete input rows');\n  String payload=JSON.serialize(new Map<String,Object>{'done'=>true,'method'=>method,'timezone'=>UserInfo.getTimeZone().getID(),'locale'=>UserInfo.getLocale(),'columns'=>columns,'rows'=>rows});\n  System.assert(payload.length()<2900,method+': complete observation exceeds bound');\n  Map<String,String> expectedByMethod=new Map<String,String>{\n   'datetimeBoundaryControls'=>'{\"rows\":[[[0,59,59],1984,1,1,0,59,59],[[0,60,0],1984,1,1,1,0,0],[[24,0,0],1984,1,2,0,0,0],[[0,1440,0],1984,1,2,0,0,0],[[0,-1,0],1983,12,31,23,59,0],[[0,0,60],1984,1,1,0,1,0]],\"columns\":[\"inputHMS\",\"year\",\"month\",\"day\",\"hour\",\"minute\",\"second\"],\"locale\":\"en_US\",\"timezone\":\"America/Los_Angeles\",\"method\":\"datetimeBoundaryControls\",\"done\":true}',\n   'originalReminderMinutes'=>'{\"rows\":[[0,1984,1,1,0,0,0,\"12:00 AM\"],[30,1984,1,1,0,30,0,\"12:30 AM\"],[60,1984,1,1,1,0,0,\"1:00 AM\"],[90,1984,1,1,1,30,0,\"1:30 AM\"],[120,1984,1,1,2,0,0,\"2:00 AM\"],[150,1984,1,1,2,30,0,\"2:30 AM\"],[180,1984,1,1,3,0,0,\"3:00 AM\"],[210,1984,1,1,3,30,0,\"3:30 AM\"],[240,1984,1,1,4,0,0,\"4:00 AM\"],[270,1984,1,1,4,30,0,\"4:30 AM\"],[300,1984,1,1,5,0,0,\"5:00 AM\"],[330,1984,1,1,5,30,0,\"5:30 AM\"],[360,1984,1,1,6,0,0,\"6:00 AM\"],[390,1984,1,1,6,30,0,\"6:30 AM\"],[420,1984,1,1,7,0,0,\"7:00 AM\"],[450,1984,1,1,7,30,0,\"7:30 AM\"],[480,1984,1,1,8,0,0,\"8:00 AM\"],[510,1984,1,1,8,30,0,\"8:30 AM\"],[540,1984,1,1,9,0,0,\"9:00 AM\"],[570,1984,1,1,9,30,0,\"9:30 AM\"],[600,1984,1,1,10,0,0,\"10:00 AM\"],[630,1984,1,1,10,30,0,\"10:30 AM\"],[660,1984,1,1,11,0,0,\"11:00 AM\"],[690,1984,1,1,11,30,0,\"11:30 AM\"],[720,1984,1,1,12,0,0,\"12:00 PM\"],[750,1984,1,1,12,30,0,\"12:30 PM\"],[780,1984,1,1,13,0,0,\"1:00 PM\"],[810,1984,1,1,13,30,0,\"1:30 PM\"],[840,1984,1,1,14,0,0,\"2:00 PM\"],[870,1984,1,1,14,30,0,\"2:30 PM\"],[900,1984,1,1,15,0,0,\"3:00 PM\"],[930,1984,1,1,15,30,0,\"3:30 PM\"],[960,1984,1,1,16,0,0,\"4:00 PM\"],[990,1984,1,1,16,30,0,\"4:30 PM\"],[1020,1984,1,1,17,0,0,\"5:00 PM\"],[1050,1984,1,1,17,30,0,\"5:30 PM\"],[1080,1984,1,1,18,0,0,\"6:00 PM\"],[1110,1984,1,1,18,30,0,\"6:30 PM\"],[1140,1984,1,1,19,0,0,\"7:00 PM\"],[1170,1984,1,1,19,30,0,\"7:30 PM\"],[1200,1984,1,1,20,0,0,\"8:00 PM\"],[1230,1984,1,1,20,30,0,\"8:30 PM\"],[1260,1984,1,1,21,0,0,\"9:00 PM\"],[1290,1984,1,1,21,30,0,\"9:30 PM\"],[1320,1984,1,1,22,0,0,\"10:00 PM\"],[1350,1984,1,1,22,30,0,\"10:30 PM\"],[1380,1984,1,1,23,0,0,\"11:00 PM\"],[1410,1984,1,1,23,30,0,\"11:30 PM\"]],\"columns\":[\"inputMinute\",\"year\",\"month\",\"day\",\"hour\",\"minute\",\"second\",\"originalLabel\"],\"locale\":\"en_US\",\"timezone\":\"America/Los_Angeles\",\"method\":\"originalReminderMinutes\",\"done\":true}',\n   'timeConstructorComparison'=>'{\"rows\":[[[0,59,59,999],0,59,59,999],[[0,60,0,0],1,0,0,0],[[24,0,0,0],0,0,0,0],[[0,0,60,0],0,1,0,0]],\"columns\":[\"inputHMSms\",\"hour\",\"minute\",\"second\",\"millisecond\"],\"locale\":\"en_US\",\"timezone\":\"America/Los_Angeles\",\"method\":\"timeConstructorComparison\",\"done\":true}'\n  };\n  System.assert(expectedByMethod.containsKey(method),method+': expected observation exists');\n  assertObserved(JSON.deserializeUntyped(expectedByMethod.get(method)),JSON.deserializeUntyped(payload),method);\n }\n @IsTest static void originalReminderMinutes(){\n  System.runAs(actor()) {\n  List<Object> rows=new List<Object>();\n  for(Integer minutes=0;minutes<=1410;minutes+=30){\n   try{\n    Datetime dt=Datetime.newInstance(1984,1,1,0,minutes,0);\n    String localeTime=dt.format().replace(dt.date().format(),'').replace(',','').trim();\n    rows.add(new List<Object>{minutes,dt.year(),dt.month(),dt.day(),dt.hour(),dt.minute(),dt.second(),localeTime});\n   }catch(Exception error){rows.add(new List<Object>{minutes,'error',error.getTypeName(),error.getMessage()});}\n  }\n  finish('originalReminderMinutes',new List<String>{'inputMinute','year','month','day','hour','minute','second','originalLabel'},rows,48);\n  }\n }\n @IsTest static void datetimeBoundaryControls(){\n  System.runAs(actor()) {\n  List<Object> rows=new List<Object>();\n  for(List<Integer> parts:new List<List<Integer>>{new List<Integer>{0,59,59},new List<Integer>{0,60,0},new List<Integer>{24,0,0},new List<Integer>{0,1440,0},new List<Integer>{0,-1,0},new List<Integer>{0,0,60}}){\n   try{\n    Datetime dt=Datetime.newInstance(1984,1,1,parts[0],parts[1],parts[2]);\n    rows.add(new List<Object>{parts,dt.year(),dt.month(),dt.day(),dt.hour(),dt.minute(),dt.second()});\n   }catch(Exception error){rows.add(new List<Object>{parts,'error',error.getTypeName(),error.getMessage()});}\n  }\n  finish('datetimeBoundaryControls',new List<String>{'inputHMS','year','month','day','hour','minute','second'},rows,6);\n  }\n }\n @IsTest static void timeConstructorComparison(){\n  System.runAs(actor()) {\n  List<Object> rows=new List<Object>();\n  for(List<Integer> parts:new List<List<Integer>>{new List<Integer>{0,59,59,999},new List<Integer>{0,60,0,0},new List<Integer>{24,0,0,0},new List<Integer>{0,0,60,0}}){\n   try{\n    Time value=Time.newInstance(parts[0],parts[1],parts[2],parts[3]);\n    rows.add(new List<Object>{parts,value.hour(),value.minute(),value.second(),value.millisecond()});\n   }catch(Exception error){rows.add(new List<Object>{parts,'error',error.getTypeName(),error.getMessage()});}\n  }\n  finish('timeConstructorComparison',new List<String>{'inputHMSms','hour','minute','second','millisecond'},rows,4);\n  }\n }\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeTimeOverflow53.cls-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\">\n    <apiVersion>53.0</apiVersion>\n    <status>Active</status>\n</ApexClass>\n")
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\": \"53.0\", \"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}]}")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 3 || got.Passed != 3 || got.Failed != 0 || got.Errors != 0 || got.Skipped != 0 {
		data, _ := json.Marshal(run)
		t.Fatalf("Time/Datetime overflow contracts: %s", data)
	}
}
